export class JuguetesComponent {
  constructor(juguetesService) {
    this.juguetesService = juguetesService;
    this.juguetes = [];
  }

  ngOnInit() {
    this.loadJuguetes();
  }

  loadJuguetes() {
    this.juguetesService.getJuguetes().subscribe(data => {
      this.juguetes = data;
    }, error => {
      console.error('Error al cargar los juguetes', error);
    });
  }

}
